RANK_ORDER = "AKQJT98765432"
_RANK_IDX = {r: i for i, r in enumerate(RANK_ORDER)}


def hand_key(c1, c2):
    """Two card strings ("As", "Kd") -> a canonical key ("AKs", "AKo", "AA").

    Returns None on anything unparseable, so callers can fall back rather than
    raise inside act().
    """
    try:
        r1, s1 = c1[0].upper(), c1[1].lower()
        r2, s2 = c2[0].upper(), c2[1].lower()
        i1, i2 = _RANK_IDX[r1], _RANK_IDX[r2]
    except Exception:
        return None
    if r1 == r2:
        return r1 + r2
    hi, lo = (r1, r2) if i1 < i2 else (r2, r1)
    return hi + lo + ("s" if s1 == s2 else "o")


def equity(c1, c2, n_opponents):
    """All-in equity for this holding against n random opponents.

    Falls back to 1/(n+1) -- the equity of a random hand -- when the holding
    cannot be parsed, which keeps the caller on a sane default.
    """
    n = n_opponents
    if n < 1:
        n = 1
    elif n > 7:
        n = 7
    k = hand_key(c1, c2)
    row = EQUITY.get(k) if k else None
    if row is None:
        return 1.0 / (n_opponents + 1) if n_opponents > 0 else 0.5
    return row[n - 1]
